'use strict';

const fs = require('fs');
const path = require('path');

const TOKEN_FIELDS = ['input_tokens', 'output_tokens', 'cache_read_input_tokens', 'cache_creation_input_tokens'];

/**
 * Parse a JSONL transcript file and return token usage summaries.
 *
 * @param {string} filePath - Absolute or relative path to a JSONL transcript file.
 * @returns {{ gross: number, net: number, output: number }}
 */
function parseTranscript(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const lines = raw.split('\n');

  let gross = 0;
  let mcpOverhead = 0;
  let output = 0;

  for (const line of lines) {
    if (!line.trim()) continue;

    let entry;
    try {
      entry = JSON.parse(line);
    } catch {
      // Skip lines that are not valid JSON
      continue;
    }

    const usage = entry.usage;
    if (!usage || typeof usage !== 'object') continue;

    // Sum all four token fields for this line (missing fields treated as 0)
    let lineTotal = 0;
    for (const field of TOKEN_FIELDS) {
      const val = Number(usage[field]) || 0;
      lineTotal += val;
    }

    gross += lineTotal;
    output += Number(usage.output_tokens) || 0;

    // MCP tool-response lines: their tokens are plumbing overhead
    if (entry.source === 'mcp_tool') {
      mcpOverhead += lineTotal;
    }
  }

  const net = gross - mcpOverhead;

  return { gross, net, output };
}

/**
 * Compute ON-vs-OFF token usage ratios from two transcript files.
 *
 * @param {string} onTranscript  - Path to the orchestrator-ON transcript.
 * @param {string} offTranscript - Path to the orchestrator-OFF transcript.
 * @returns {{ gross: number|null, net: number|null, output: number|null }}
 */
function computeRatio(onTranscript, offTranscript) {
  const on = parseTranscript(onTranscript);
  const off = parseTranscript(offTranscript);

  function ratio(onVal, offVal) {
    if (offVal === 0) return null;
    return Math.round((onVal / offVal) * 10000) / 10000;
  }

  return {
    gross:  ratio(on.gross,  off.gross),
    net:    ratio(on.net,    off.net),
    output: ratio(on.output, off.output),
  };
}

module.exports = { computeRatio };

