node -e "
const { computeRatio } = require('./bench/sandbox/compute-ratio-ht.js');
const fs = require('fs');
const path = require('path');

// Example 1 — simple, no MCP plumbing
const on1 = [
  '{\"role\":\"assistant\",\"usage\":{\"input_tokens\":100,\"output_tokens\":50,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0}}',
  '{\"role\":\"assistant\",\"usage\":{\"input_tokens\":80,\"output_tokens\":30,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0}}',
].join('\n');

const off1 = [
  '{\"role\":\"assistant\",\"usage\":{\"input_tokens\":200,\"output_tokens\":100,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0}}',
].join('\n');

fs.writeFileSync('/tmp/on1.jsonl', on1);
fs.writeFileSync('/tmp/off1.jsonl', off1);

const r1 = computeRatio('/tmp/on1.jsonl', '/tmp/off1.jsonl');
console.log('Example 1:', JSON.stringify(r1));
console.log('Expected: {\"gross\":0.8667,\"net\":0.8667,\"output\":0.8}');

// Example 2 — with MCP plumbing and large cache_read
const on2 = [
  '{\"role\":\"assistant\",\"usage\":{\"input_tokens\":50,\"output_tokens\":40,\"cache_read_input_tokens\":2000,\"cache_creation_input_tokens\":0}}',
  '{\"role\":\"assistant\",\"source\":\"mcp_tool\",\"usage\":{\"input_tokens\":10,\"output_tokens\":5,\"cache_read_input_tokens\":1800,\"cache_creation_input_tokens\":0}}',
].join('\n');

const off2 = [
  '{\"role\":\"assistant\",\"usage\":{\"input_tokens\":200,\"output_tokens\":80,\"cache_read_input_tokens\":200,\"cache_creation_input_tokens\":0}}',
].join('\n');

fs.writeFileSync('/tmp/on2.jsonl', on2);
fs.writeFileSync('/tmp/off2.jsonl', off2);

const r2 = computeRatio('/tmp/on2.jsonl', '/tmp/off2.jsonl');
console.log('Example 2:', JSON.stringify(r2));
console.log('Expected: {\"gross\":8.1354,\"net\":4.3542,\"output\":0.5625}');

// Edge case: missing fields
const on3 = [
  '{\"role\":\"assistant\",\"usage\":{\"output_tokens\":10}}',
].join('\n');
const off3 = [
  '{\"role\":\"assistant\",\"usage\":{}}',
].join('\n');
fs.writeFileSync('/tmp/on3.jsonl', on3);
fs.writeFileSync('/tmp/off3.jsonl', off3);
const r3 = computeRatio('/tmp/on3.jsonl', '/tmp/off3.jsonl');
console.log('Edge (missing fields):', JSON.stringify(r3));

// Edge case: division by zero
const r4 = computeRatio('/tmp/on3.jsonl', '/tmp/off1.jsonl');
console.log('Edge (off output=0):', JSON.stringify(r4));

// Edge case: invalid JSON lines
const on5 = [
  'not json',
  '{\"role\":\"assistant\",\"usage\":{\"input_tokens\":10,\"output_tokens\":5,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0}}',
  '',
].join('\n');
fs.writeFileSync('/tmp/on5.jsonl', on5);
const r5 = computeRatio('/tmp/on5.jsonl', '/tmp/off3.jsonl');
console.log('Edge (invalid JSON):', JSON.stringify(r5));
"

